#!/bin/sh
# mkbox.sh <box name> <tool>...: the C source of a multi-call program for
# sbase's tools (the same idea as upstream's scripts/mkbox, which wants its
# own build tree): each tool's main is compiled as <tool>_main (-Dmain=),
# and this main picks one by the basename of argv[0], the name the program
# was started as (the shell starts a program by its bootfs name, usr/bin/sort).
# Started as the box's own name, it takes the tool from the first argument:
# `sbase-rw sort file`; with none, it lists its tools.
set -eu
box=$1
shift
cat <<EOF
/* Generated by ports/sbase/files/mkbox.sh: the multi-call program $box. */
#include <libgen.h>
#include <stdio.h>
#include <string.h>

EOF
for t in "$@"; do
    printf 'int %s_main(int, char **);\n' "$(printf %s "$t" | tr - _)"
done
cat <<EOF

static const struct { const char *name; int (*fn)(int, char **); } cmds[] = {
EOF
for t in "$@"; do
    printf '\t{ "%s", %s_main },\n' "$t" "$(printf %s "$t" | tr - _)"
done
cat <<EOF
	{ NULL, NULL },
};

int
main(int argc, char *argv[])
{
	char copy[256];
	const char *s;
	int i;

	strncpy(copy, argv[0], sizeof(copy) - 1);
	copy[sizeof(copy) - 1] = '\0';
	s = basename(copy);
	if (!strcmp(s, "$box") && argc > 1) {
		argc--;
		argv++;
		strncpy(copy, argv[0], sizeof(copy) - 1);
		s = basename(copy);
	}
	for (i = 0; cmds[i].name; i++) {
		if (!strcmp(cmds[i].name, s))
			return cmds[i].fn(argc, argv);
	}
	for (i = 0; cmds[i].name; i++)
		printf("%s ", cmds[i].name);
	putchar('\n');
	return s == NULL || !strcmp(s, "$box") ? 0 : 127;
}
EOF
